window.MONSTER_CHUNK_20 = [{"name":"Ogrekin","cr":2,"xp":600,"race":"human ogrekin","classes":[{"class":"fighter","level":2}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["giant"],"init":5,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+1 Dex, +3 natural","hp":25,"hd":"2d10+10","hdvalue":2,"fort":7,"ref":1,"will":1,"defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"shortspear +7 (1d6+5), bite +2 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":21,"dexterity":13,"constitution":18,"intelligence":8,"wisdom":12,"charisma":6,"baseatk":2,"cmb":7,"cmd":18,"feats":[{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":10},{"skill":"Swim","value":10}],"languages":["Giant"],"sq":[{"type":"deformities","details":"oversized maw, weak mind"}],"environments":["any"],"organizations":["solitary","family (2-6)"],"treasure":"none","description_visual":"Its body twisted and deformed, this lumbering giant has tiny eyes and a mouth of jagged teeth presented in a furious roar.","group":"Ogrekin","source":"PFRPG Bestiary 2","description":"The result of an unfortunate union between an ogre and a humanoid, the ogrekin (or half-ogre) is cursed with horrific malformations due to its tragic ancestry. Shunned by both parents, ogrekin tend to form unstable clans of their own, often resorting to inbreeding to sustain the collective. While good-natured ogrekin are not entirely unheard of, they are far and few between.","ecology":"","habitat_society":"","gear":"spear"},{"name":"Ovinnik","cr":2,"xp":600,"alignment":"CN","size":"Tiny","type":"fey","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+3 Dex, +2 natural, +2 size","hp":22,"hd":"4d6+8","hdvalue":4,"fort":3,"ref":7,"will":6,"dr":"2/cold iron","resists":[{"type":"fire","value":5}],"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"2 claws +7 (1d3+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"luck touch"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"daze"},{"spell":"produce flame"}]},{"frequency":"1/month","spells":[{"spell":"divination"}]}],"strength":12,"dexterity":17,"constitution":15,"intelligence":9,"wisdom":14,"charisma":16,"baseatk":2,"cmb":3,"cmd":14,"feats":[{"feat":"Go Unnoticed"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Climb","value":9},{"skill":"Escape Artist","value":10},{"skill":"Intimidate","value":5},{"skill":"Knowledge (local)","value":4},{"skill":"Knowledge (nature)","value":4},{"skill":"Perception","value":9},{"skill":"Stealth","value":18}],"languages":["Common","Sylvan"],"sq":[{"type":"compression"}],"environments":["any land"],"organizations":["solitary"],"treasure":"none","description_visual":"Covered in sleek black fur, this vaguely feline humanoid holds flickering flames in its clawed hand.","source":"AP 67","special_abilities":[{"type":"Luck Touch","kind":"Su","details":"With a claw attack or touch attack, an ovinnik can alter a creature's luck. If the target fails a DC 14 Will save, it either gains a +4 bonus or takes a -4 penalty (ovinnik's choice) on its next three d20 rolls. The target can choose to automatically fail the saving throw, but must choose before it knows whether the touch will be beneficial or harmful. The save DC is Charisma-based."}],"description":"Ovinniks make their homes in granaries and drying houses. These thin, sleek, black-furred humanoids stand only a foot high. Their eyes and features seem catlike, but they bark like dogs to scare away thieves. No one knows why an ovinnik chooses to take up residence in a particular farm's threshing house, and few would call on them willingly. A wise farmer placates resident ovinniks with frequent gifts of warm milk, pancakes, or dead roosters. By tradition, before the new year farmers and their families go to the granary to learn their fates for the coming year. The ovinnik touches each of them in turn. If the touch is warm, the person will have good luck; if cold, she will suffer terrible misfortune in the days ahead.","ecology":"","habitat_society":""},{"name":"Panda","cr":2,"xp":600,"alignment":"N","size":"Medium","type":"animal","init":0,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+3 natural","hp":19,"hd":"3d8+6","hdvalue":3,"fort":5,"ref":3,"will":1,"speed":[{"type":"land","speed":30}],"melee":"bite +5 (1d6+6), 2 claws +5 (1d3+3)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":10,"constitution":15,"intelligence":2,"wisdom":11,"charisma":14,"baseatk":2,"cmb":5,"cmd":15,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":11},{"skill":"Perception","value":7},{"skill":"Survival","value":1}],"sq":[{"type":"powerful bite"}],"environments":["temperate jungles","warm jungles"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This black-and-white-furred bear is about as long in the body as an average human-but much rounder.","source":"Animal Archive","special_abilities":[{"type":"Powerful Bite","kind":"Ex","details":"A panda applies twice its Strength bonus to bite damage."}],"description":"Pandas spend most of their lives alone, avoiding even other pandas except during mating season. They are excellent climbers, with front paws configured much like humans' opposable thumbs to help them grip bamboo stalks and tree branches. Bamboo shoots make up almost their entire diet, although pandas are technically omnivorous. In part because of the low nutritional value of bamboo, pandas lack the energy for aggression, and avoid danger wherever possible.","ecology":"","habitat_society":""},{"name":"Panotti","cr":2,"xp":600,"alignment":"NG","size":"Medium","type":"humanoid","init":1,"senses":[{"type":"blindsense","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+2 armor, +1 Dex, +1 dodge, +2 natural","hp":19,"hd":"3d8+6","hdvalue":3,"fort":5,"ref":2,"will":2,"speed":[{"type":"land","speed":30},{"type":"fly","speed":20,"maneuverability":"poor"}],"melee":"short sword +4 (1d6+2/19-20) or   2 wings +2 (1d4+1 plus push, 10 ft.)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":13,"constitution":14,"intelligence":10,"wisdom":12,"charisma":11,"baseatk":2,"cmb":4,"cmd":16,"feats":[{"feat":"Dodge"},{"feat":"Hover","type":"bonus"},{"feat":"Multiattack"}],"skills":[{"skill":"Fly","value":3},{"skill":"Perception","value":2,"special":"+6 listening only"},{"skill":"Survival","value":6}],"languages":["Common"],"sq":[{"type":"elephantine ears"}],"environments":["any land"],"organizations":["solitary","pair","tribe (5-11)"],"treasure":"none","description_visual":"This bald humanoid looks strikingly human except for the long folds of skin that droop from his head and neck to just above his ankles.","source":"Murder's Mark","special_abilities":[{"type":"Elephantine Ears","kind":"Ex","details":"A panotti can flap its huge ears to fly awkwardly. A panotti can also wrap its ears around the length of its body for warmth and protection from the elements (similar to using a bedroll or heavy blankets), or use them as secondary natural attacks (as per wing attacks)."}],"description":"The panotti are a race of humanoids that strongly resemble humans except for one startling difference: their enormous ears. A panotti's ears are attached to the side of their heads, like those of a human, but they remain connected to the body down to the neck. When at ease, the folds of their ears hang loosely, like an elephant's, but extend almost the length of their bodies. These sheets of hanging flesh and skin appear limp and superfluous, but appearances are deceiving. Panotti possess remarkably smooth muscle control along the upper ridges of their ears, allowing them to extend and control their ears at will.\n\nEven though panotti look ridiculous by most humanoid standards, the source of this ridicule offers them several distinct advantages. By flapping their ears, adult panotti can lift off, hover, and even fly. While in combat, a panotti can slam opponents with its ears to propel them away. Panotti's hearing is sharp enough to detect the presence of even an unseen adversary. Finally, panotti can wrap themselves up in their ears like a cocoon, staying warm on the coolest of nights. Some sages speculate the panotti originated in a kingdom that fell beneath a curse-though the panotti themselves deny it. The rare couplings between a human and a panotti usually result in panotti children.\n\nCulturally, the panotti are a reclusive people, preferring the company of their own kind—mostly due to the reaction they receive from other humanoids. Nevertheless, panotti are not a cruel or unkind race, and their culture is rich with music and storytelling traditions. They adapt to most classes with ease, but favor bard, fighter, and ranger. Treated with respect and dignity, panotti can be generous and steadfast allies. When treated as laughingstocks, however, panotti can become fierce, and they're naturally hearty and capable warriors.\n\nOn Golarion, panotti live primarily in Casmaron and central Tian Xia, with a much smaller number residing in Avistan.","ecology":"","habitat_society":"","gear":"leather armor, short sword"},{"name":"Paracletus","cr":2,"xp":600,"alignment":"N","size":"Small","type":"outsider","subtypes":["aeon","extraplanar"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["emotion aura (DC 12, 30 ft.)"],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":13,"hd":"3d10-3","hdvalue":3,"fort":4,"ref":3,"will":6,"immunities":["cold","critical hits","poison"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":7,"speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"slam +3 (1d3-1 plus 1d6 electricity)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"sanctuary"}]},{"frequency":"3/day","spells":[{"spell":"calm emotions"}]},{"frequency":"1/week","spells":[{"spell":"commune"}]}],"strength":8,"dexterity":14,"constitution":9,"intelligence":11,"wisdom":13,"charisma":12,"baseatk":3,"cmb":1,"cmd":13,"cmd_special":"can't be tripped","feats":[{"feat":"Great Fortitude"},{"feat":"Iron Will"}],"skills":[{"skill":"Fly","value":8},{"skill":"Intimidate","value":7},{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":12}],"languages":["envisaging"],"sq":[{"type":"extension of all"},{"type":"void form"}],"environments":["any (Outer Planes)"],"organizations":["solitary","pair","commune (3-12)"],"treasure":"none","description_visual":"A small cluster of shimmering lights floats in the air, orbited by multiple vibrant crystals and gemstones.","group":"Aeon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Emotion Aura","kind":"Sp","details":"Each paracletus exists as the embodiment of a specific emotive duality. Three times per day, a paracletus can create an aura representing one of its two programmed emotions. Creatures in the area must make a DC 12 Will save to resist the aura. A creature that makes its save against the aura is unaffected by that aeon's aura for the next 24 hours. The paracletus can choose one creature in the area to ignore its effects. The effect of the aura lasts for 10 minutes, and ends if a creature moves more than 30 ft. from the aeon. The aura is a mind-affecting compulsion effect. The save DC is Charisma-based. Specific emotive dualities and their powers follow-any single paracletus can only use one of these three dualistic options and cannot change to a different one. Courage/Fear: The aura acts as bless or bane. Empathy/Apathy: The aura gives creatures a +2 bonus or a -2 penalty on Bluff, Diplomacy, and Intimidate checks. Hope/Despair: The aura gives creatures a +2 morale bonus on Will saving throws or a -2 penalty on Will saving throws."}],"description":"While mortals possess the gift of free will, both logic and emotion inf luence their decisions. The paracletus serve the aeons as agents who connect with mortals and study the inf luence of emotions (particularly the dualistic nature of raw emotion) upon mortal behavior. They wander the planes seeking mortals with particularly strong emotional or logical capabilities (characters with high Charisma or Intelligence scores). Once a paracletus locates such a creature, the paracletus remains nearby, studying the target's relationship with emotional and logical input and choices. Often, the paracletus will use its emotion aura on the target in order to study how outside inf luences affect the subject. Unfortunately for the target creature, whether or not the paracletus uses a helpful or harmful effect is, for all intents and purposes, a matter of random chance-even though to the paracletus's complex reasoning, nothing is left to actual random chance.\n\nIf presented the option, a paracletus avoids direct combat, and uses its emotion aura to inf luence situations. If pressed to defend itself, it flies at opponents, slamming into them and discharging an electrical jolt of energy in addition to buffeting with its crystalline components. The crystals that orbit a paracletus are solidified aspects of logic, while the swirling vapors and lights that make up its central mass are manifestations of raw emotion- when a paracletus is slain, both the crystals and vapors fade away into nothingness.\n\nA paracletus can be chosen as a familiar by a 7th-level neutral spellcaster who has the Improved Familiar feat. A paracletus familiar doesn't abandon its mission to observe emotions and logic at play, but it does follow its master's orders-this is one situation where the application of a paracletus's emotion aura need not be random.\n\nAlthough the central mass of a paracletus's body appears to be made of light and energy, it is in fact solid, and feels strangely like electrified flesh to the touch.","ecology":"","habitat_society":""},{"name":"Pilo","cr":2,"xp":600,"alignment":"N","size":"Small","type":"animal","init":1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+1 Dex, +2 natural, +1 size","hp":19,"hd":"3d8+6","hdvalue":3,"fort":5,"ref":4,"will":3,"defensive_abilities":["roll up"],"speed":[{"type":"land","speed":30}],"melee":"gore +4 (1d6+1 plus poison), tail slap -1 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"},{"type":"quills"}],"strength":13,"dexterity":13,"constitution":14,"intelligence":2,"wisdom":14,"charisma":7,"baseatk":2,"cmb":2,"cmb_special":"+2 vs. bull rush","cmd":13,"cmd_special":"+2 vs. bull rush, +8 vs. trip","feats":[{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":8}],"environments":["any deserts"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"Sharp quills cover this bright yellow, six-legged animal, and its long, twitching snout probes the air around it.","source":"AP 85","special_abilities":[{"type":"Poison","kind":"Ex","details":"Quills-injury; save Fort DC 13; frequency 1/round for 4 rounds; effect 1d2 Dex; cure 1 save."},{"type":"Quills","kind":"Ex","details":"Any creature attacking a pilo with natural weapons or an unarmed strike takes 1d6 points of piercing damage. A creature that grapples a pilo takes 2d6 points of piercing damage each round it is engaged in a grapple. A pilo can also use its quills to damage any opponent it successfully bull rushes. Any creature that takes damage from a pilo's quills risks being poisoned."},{"type":"Roll Up","kind":"Ex","details":"As a move action, a pilo can tuck itself into a ball. This grants the pilo a +4 bonus to its natural armor, but its speed is reduced to 10 ft."}],"description":"These carnivorous marsupials, sometimes called tumblespikes, are irritable desert-dwelling creatures that even predators leave alone. They are aggressive and often attack creatures that are larger than themselves. Pilos plow toward their foes and attempt to gore these foes with their spikes, bellowing a wheezing series of grunts. When provoked by a creature much larger than themselves or a particularly dangerous predator, pilos roll up into a spiny ball to deter attacks. Their aggressive nature means that they often fight until they die or until their opponent perishes or flees. Though pilos are only 3 ft. long, their muscular bodies and spikes-which constantly grow-contribute to their 80-pound weight. Like many marsupials, pilos carry their young in a pouch, which they protect by remaining rolled up except when hunting.","ecology":"","habitat_society":""},{"name":"Pipefox","cr":2,"xp":600,"alignment":"N","size":"Diminutive","type":"magical beast","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+3 Dex, +4 size","hp":13,"hd":"3d10-3","hdvalue":3,"fort":2,"ref":6,"will":1,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"bite +10 (1d2-5)","space":"1 ft.","reach":"0 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"comprehend languages"}]},{"frequency":"1/day","spells":[{"spell":"detect thoughts"},{"spell":"divination"},{"spell":"greater invisibility","details":"self only"}]},{"frequency":"3/day","spells":[{"spell":"augury"},{"spell":"vanish"}]}],"strength":1,"dexterity":16,"constitution":9,"intelligence":14,"wisdom":11,"charisma":14,"baseatk":3,"cmb":2,"cmd":8,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":7},{"skill":"Knowledge (arcana)","value":5},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":5},{"skill":"Sense Motive","value":2},{"skill":"Stealth","value":19}],"languages":["Common","Draconic","comprehend languages"],"sq":[{"type":"compression"}],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"This furry, minute serpent has a foxlike head and tiny eyes that glitter with intelligence.","source":"PFRPG Bestiary 4","description":"A pipefox is a foot-long, furry, magical snake with the head of a fox. Often found either climbing in trees or snaking around pipes, these curious and stealthy creatures prefer to skulk about to observe and learn. Neither malicious nor particularly beneficial, pipefoxes love to gather knowledge and sometimes disseminate what they've acquired to those they find worthy. Desirous of knowledge, no matter how obscure, these creatures only see other like-minded creatures worthy of their interaction. Though they might become curious about a tribe of barbarians, take sudden interest in learning the cant of a local group of thieves, or even study the method of distribution for the local brewery, they watch such things from a distance, never interacting with such \"lesser minds.\" But if a pipefox finds a creature that loves knowledge as much as it does, it becomes intrigued, and after spending a period of time observing such a creature, will eventually muster up the courage to make the relationship more personal. Many pipefoxes are especially intrigued by spellcasters, and sometimes they offer to serve them as either familiars or confidants. Pipefoxes are secretive by nature, and even when they make themselves known, they can be shy and evasive, both physically and intellectually. They often see knowledge as a type of spiritual currency, and are hesitant to give their knowledge away unless they gain something in return. Some believe pipefoxes are the spirits of legendary scribes and lore masters given new form. Others believe the creatures are related to kami, and serve to preserve the world's knowledge. A spellcaster of at least 7th level who has the Improved Familiar feat may select the pipefox as a familiar, but only after the pipefox has agreed to pledge its services to the spellcaster.","ecology":"","habitat_society":""},{"name":"Plagued Steed","cr":2,"xp":600,"race":"horse","alignment":"NE","size":"Large","type":"undead","subtypes":["augmented animal"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+3 Dex, +2 natural, -1 size","hp":16,"hd":"2d8+7","hdvalue":2,"fort":5,"ref":6,"will":1,"defensive_abilities":["channel resistance +2"],"dr":"5/slashing","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":50}],"melee":"bite +5 (1d8+5 plus disease), 2 hooves +0 (1d4+2)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"disease"}],"strength":20,"dexterity":16,"intelligence":2,"wisdom":13,"charisma":15,"baseatk":1,"cmb":7,"cmd":20,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Run","type":"bonus"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Perception","value":6}],"sq":[{"type":"docile"}],"treasure":"none","description_visual":"This fanged horse is in an advanced state of decay, yet despite its dripping maggots, it moves as if it were very much alive.","group":"Plagued Beast","source":"The Worldwound","special_abilities":[{"type":"Disease","kind":"Ex","details":"Demon Plague: Bite—injury; save Fortitude DC 13; onset 1 day; frequency 1/day; effect 1d3 Constitution damage and 1d6 Wisdom damage, victim is fatigued if it takes any ability damage from the disease, and certain creatures slain by demon plague rise as plagued beasts; cure 3 consecutive saves."}],"description":"The demonplague has a particularly hideous effect on animals and other unintelligent beasts that succumb to its ravages-fallen creatures arise from death and continue to spread the vile plague with their bite. Certain demons and humanoid cultists are fond of using plagued beast horses as mounts.","ecology":"","habitat_society":""},{"name":"Poltergeist","cr":2,"xp":600,"alignment":"LE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":12,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+1 deflection, +1 Dex","hp":16,"hd":"3d8+3","hdvalue":3,"fort":2,"ref":2,"will":4,"defensive_abilities":["incorporeal","natural invisibility","rejuvenation"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":20,"maneuverability":"perfect"}],"space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"frightener"},{"type":"telekinesis"}],"dexterity":13,"intelligence":5,"wisdom":12,"charisma":12,"baseatk":2,"cmb":3,"cmd":14,"feats":[{"feat":"Ability Focus (fear)"},{"feat":"Alertness"}],"skills":[{"skill":"Fly","value":9},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":3}],"languages":["Common"],"sq":[{"type":"site bound"}],"environments":["any"],"organizations":["solitary","haunting (2-7)"],"treasure":"incidental","description_visual":"A ghostly, skeletal figure rises up amid a whirling cyclone of tools, plates, utensils, and other loose objects.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Frightener","kind":"Su","details":"Once per minute as a standard action, a poltergeist can temporarily drop its natural invisibility, revealing itself to be a skeletal, ghost-like humanoid. All creatures within 30 ft. when a poltergeist uses this ability must make a DC 14 Will save to avoid becoming frightened for 1d4 rounds. The poltergeist then resumes its invisibility at the end of its turn as a free action. A creature that successfully saves is immune to the fear effect of that poltergeist for 24 hours. If the poltergeist's natural invisibility is negated via other methods, it cannot use this ability. Likewise, those that can see invisible creatures are immune to this special attack. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Rejuvenation","kind":"Su","details":"When a poltergeist is destroyed, it only remains destroyed for 2d4 days. After this time, the undead spirit reforms where it was destroyed, fully healed. The only way to permanently destroy a poltergeist is to determine the reason for its existence and set right whatever prevents it from resting in peace. The exact means varies with each spirit and may require a good deal of research, and should be created specifically for each different poltergeist or group of poltergeists by the GM."},{"type":"Site Bound","kind":"Ex","details":"A poltergeist cannot travel more than 120 ft. from the point at which it was created or formed."},{"type":"Telekinesis","kind":"Su","details":"A poltergeist has no method of attacking apart from telekinesis. This ability functions as the spell telekinesis, with a CL equal to the poltergeist's Hit Dice (CL 3rd for most poltergeists). A typical poltergeist has a ranged attack roll of +3 when using telekinesis to hurl objects or creatures, and can use the ability on objects or creatures of up to 75 pounds. If a poltergeist attempts to hurl a creature with this ability, that creature can resist the effect with a successful DC 12 Will save. The save DC is Charisma-based."}],"description":"A poltergeist is an angry spirit that forms from the soul of a creature that, for whatever reason, becomes unable to leave the site of its death. Sometimes, this might be due to an unfinished task- other times, it might be due to a powerful necromantic effect. Desecrating a grave site by building a structure over the body below is the most common method of accidentally creating a poltergeist. The poltergeist experiences great trauma over its condition; this trauma twists its psyche to evil and fosters an overall hatred of the living expressed in outbursts of rage. A poltergeist is bound to a specific place, usually a building, room, or recognizable area (a section of a cemetery, a stretch of lonely road, and so on). This place typically corresponds to its place of death or the resting place of its mortal remains.","ecology":"","habitat_society":""},{"name":"Pooka","cr":2,"xp":600,"alignment":"CN","size":"Tiny","type":"fey","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 natural, +2 size","hp":18,"hd":"4d6+4","hdvalue":4,"hp_mods":["fast healing 2"],"fort":2,"ref":7,"will":5,"dr":"5/cold iron or silver","sr":13,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"dagger +7 (1d2/19-20)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"poison"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect magic"},{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"suggestion"}]},{"frequency":"3/day","spells":[{"spell":"minor image"},{"spell":"sleep"}]}],"strength":10,"dexterity":16,"constitution":13,"intelligence":11,"wisdom":12,"charisma":13,"baseatk":2,"cmb":3,"cmd":13,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Diplomacy","value":8},{"skill":"Fly","value":18},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":6},{"skill":"Stealth","value":18},{"skill":"Use Magic Device","value":6}],"languages":["Common","Sylvan","telepathy (touch)"],"sq":[{"type":"change shape","details":"2 of the following forms: cat, goat, rabbit [use stats for raccoon], or raven; polymorph"}],"environments":["any"],"organizations":["solitary","pair","ruse (3-9)"],"treasure":"standard","description_visual":"This creature combines the features of a sprightly girl and a black rabbit. A wicked, whimsical grin gleams on her face.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Poison","kind":"Su","details":"As a standard action, a pooka can blow across her palm and create a 5-foot-diameter cloud of intoxicating dust. The pooka decides when she uses this ability whether the dust acts as an inhaled poison or a mild intoxicant (equivalent to 1-2 glasses of beer)."},{"type":"Pooka Dust","kind":"Su","details":": Inhaled; save Fort DC 13; frequency 1/round for 6 rounds; effect 1d2 Wis and 1d2 Cha (or intoxication); cure 2 consecutive saves."}],"description":"Capricious in nature, pookas are always in search of fun, though they don't often care who they inconvenience with their antics-they're just in it for the whimsy. Always chaotic in nature, some pookas are cruel, some are good-natured, and others are slightly unhinged. There's no way to tell which kind one is just by looking at it; only by interacting with a pooka does its nature become clear. However, having a conversation with a pooka isn't easy. Though they're intelligent, pookas speak in choppy, simple sentences filled with obscure metaphors and nonsensical references. Most creatures who converse with a pooka usually misunderstand it the first time and have to ask the creature to repeat itself. Even their telepathy is filled with strange images and references, such as representing the word \"elf \" with the face of an elf it knew long ago, colloquialisms that only make sense to native speakers of Sylvan, and so on. Pookas thrive when in the company of others, and they frequently find companionship in a particular individual whether the camaraderie is wanted or not. Pookas prefer creatures of chaotic alignments, don't trust those with lawful alignments, and find most people with neutral alignments boring. Pookas pull pranks to get to know a person and stay near them to observe the results, invisibly perched on a shoulder or clinging to an article of clothing. As they usually communicate with their unlucky target (whom they call \"friend\") using telepathy, the person's erratic reactions to the unseen pooka's pranks and mental \"voice\" can make the target appear insane. The pooka doesn't mind a little rough retaliation, but flees any attempts to kill it. Some pookas can be helpful, and farmers often leave a portion of their harvest behind as a tribute for any resident pookas. A pooka who is satisfied with such a gift may leave that farmer alone for an entire year, while a pooka who feels slighted by the offering may relentlessly mock the farmer and cause minor accidents on the farm. A pooka measures 1 to 2 ft. from eartips to tail and weighs up to 15 pounds. A non-lawful spellcaster of at least 7th level who takes the Improved Familiar feat can select a pooka as a familiar.","ecology":"","habitat_society":""},{"name":"Pseudosphinx","cr":2,"xp":600,"alignment":"N","size":"Tiny","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":15,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 natural, +2 size","hp":16,"hd":"3d10","hdvalue":3,"fort":3,"ref":5,"will":6,"dr":"5/magic","sr":13,"speed":[{"type":"land","speed":20},{"type":"fly","speed":30,"maneuverability":"average"}],"melee":"bite +2 (1d3-3), 2 claws +2 (1d2-3)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"aided insight"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"comprehend languages"}]},{"frequency":"at-will","spells":[{"spell":"detect magic"},{"spell":"detect secret doors"}]},{"frequency":"3/day","spells":[{"spell":"burning hands"},{"spell":"cause fear"},{"spell":"identify"},{"spell":"vanish"}]}],"strength":5,"dexterity":14,"constitution":11,"intelligence":9,"wisdom":16,"charisma":12,"baseatk":3,"cmb":3,"cmd":10,"feats":[{"feat":"Alertness"},{"feat":"Iron Will"}],"skills":[{"skill":"Fly","value":6},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":5}],"languages":["Common","Sphinx"],"environments":["warm deserts"],"organizations":["solitary"],"treasure":"standard","description_visual":"This small creature has the body of a housecat, the wings of a falcon, and the head of a monkey.","source":"Familiar Folio","special_abilities":[{"type":"Aided Insight","kind":"Su","details":"Once per day, a pseudosphinx can tap into the wisdom of its ancestors to answer a question for another creature. To do so, the pseudosphinx attempts a Wisdom check, gaining a bonus on the check equal to the querent's level and treating the result of the check as the result of an appropriate Knowledge check. The pseudosphinx must be touching the querent to use this ability."}],"description":"Pseudosphinxes are cat-sized, fairylike creatures thought to be distant cousins to the larger and better-known true sphinxes. They most resemble gynosphinxes, though the pseudosphinxes' monkeylike heads and tiny bodies ensure that the two species are never confused for each other. A typical pseudosphinx is 2 ft. long and weighs 10 pounds.\n\nPseudosphinxes are rarely found in groups, and scholars are unsure whether to attribute their cryptic origins to elusive demeanors or amnesic memories. Whether they're the misbegotten progeny of generations of lesser sphinxes or the result of some magical experiment in the same deserts where sphinxes are found, none can say.\n\nA pseudosphinx can serve as the familiar for a 7th-level spellcaster with the Improved Familiar feat.","ecology":"","habitat_society":""},{"name":"Quasit","cr":2,"xp":600,"alignment":"CE","size":"Tiny","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 Dex, +2 natural, +2 size","hp":16,"hd":"3d10","hdvalue":3,"hp_mods":["fast healing 2"],"fort":1,"ref":5,"will":4,"dr":"5/cold iron or good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":20},{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"2 claws +7 (1d3-1 plus poison), bite +7 (1d4-1)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect good"},{"spell":"detect magic"},{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"cause fear","details":"30 foot radius"}]},{"frequency":"1/week","spells":[{"spell":"commune","details":"six questions"}]}],"strength":8,"dexterity":14,"constitution":11,"intelligence":11,"wisdom":12,"charisma":11,"baseatk":3,"cmb":0,"cmd":12,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Fly","value":20},{"skill":"Intimidate","value":6},{"skill":"Knowledge (planes)","value":6},{"skill":"Perception","value":7},{"skill":"Stealth","value":16}],"languages":["Abyssal","Common","telepathy (touch)"],"sq":[{"type":"change shape","details":"2 of the following forms: bat, Small centipede, toad, or wolf; polmorph"}],"environments":["any (Abyss)"],"organizations":["solitary","flock (2-12)"],"treasure":"standard","description_visual":"Ram horns curl back from the twisted head of this tiny winged demon, and its body is thin and wiry.","group":"Demon","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Claw-injury; save Fortitude DC 13; frequency 1/round for 6 rounds; effect 1d2 Dexterity; cure 2 consecutive saves."}],"description":"The quasit is perhaps the least powerful demon, yet it isn't the least respected-even quasits hold themselves above the dretch horde, and true to their natures, dretches lack the courage or drive to prove the quaits wrong. A quasit's first role in life is that of a familiar to a spellcasting master, but those quasits who escape from this humiliating servitude become free-willed and much more dangerous. A typical quasit stands a foot and a half tall, and weighs only 8 pounds. Alone among the demonic horde, quasits don't form from the dead souls of evil mortals. Instead, they form from living souls-when a spellcaster seeks out a quasit to serve him as a familiar, his soul brushes against the Abyss and it reacts, carving from itself a quasit linked to that spellcaster's soul and forming a powerful bond between the two. Newly created quasits are birthed directly into the Material Plane, where they become familiars, and while bonded to their masters' wills, all quasits hate and loathe their lieges, as they can feel the pulse of their lords' souls and know that they could have been more. A quasit serves, yet it watches and waits for mistakes that might cost its master's life, or even better, an error that might let the quasit turn against its master. When a quasit's master dies, the quasit can attempt to follow the master's soul into the Great Beyond by making a DC 15 Will save. This functions as plane shift, but affects only the quasit and transports it into the Abyss and places its master's soul in the quasit's possession as a writhing larvae rather than using the evil master's soul to create new demonic life. In this manner, a quasit can use its newly captured soul to bargain with more powerful denizens of the lower planes, and perhaps secure a vile transformative \"promotion\" to a more powerful form of life in the process. Rarely, a quasit elects to ignore its master's death and instead remains on the Material Plane to seek other ways to entertain itself-usually settling in an urban area where there are plenty of folk to torment.","ecology":"","habitat_society":""},{"name":"Raktavarna Rakshasa","cr":2,"xp":600,"alignment":"LE","size":"Tiny","type":"outsider","subtypes":["native","rakshasa","shapechanger"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"}],"ac":17,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+3 Dex, +2 natural, +2 size","hp":22,"hd":"3d10+6","hdvalue":3,"fort":3,"ref":6,"will":4,"dr":"5/good or piercing","sr":17,"speed":[{"type":"land","speed":20},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"bite +8 (1d4-2 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"detect thoughts","details":"DC 13"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"comprehend languages"}]},{"frequency":"1/day","spells":[{"spell":"charm person"},{"spell":"suggestion"}]},{"frequency":"1/week","spells":[{"spell":"commune"}]}],"strength":7,"dexterity":16,"constitution":15,"intelligence":12,"wisdom":13,"charisma":14,"baseatk":3,"cmb":4,"cmd":12,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Climb","value":14},{"skill":"Disguise","value":16},{"skill":"Escape Artist","value":6},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":9},{"skill":"Stealth","value":17},{"skill":"Swim","value":11}],"languages":["Common","Infernal","Undercommon","comprehend languages"],"sq":[{"type":"change shape","details":"Tiny living object"},{"type":"master's eyes"}],"environments":["any"],"organizations":["solitary","pair","rack (3-10)"],"treasure":"standard","description_visual":"What at first appears to be a bejeweled blade shimmers and writhes, transforming into a hideous, red-eyed serpent.","group":"rakshasa","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Change Shape","kind":"Su","details":"As a full-round action, a raktavarna can take the shape of a handheld object, most often an ornamental light, a one-handed weapon, or a piece of treasure. If the rakshasa remains stationary in such a form, it can attempt Stealth checks even while being observed. It can remain motionless in object form indefinitely, but reverts to its true form as soon as it takes any action."},{"type":"Master's Eyes","kind":"Su","details":"A raktavarna can designate a single creature as its master as a standard action. If the raktavarna is a spellcaster's familiar, its master is automatically that spellcaster, and the raktavarna cannot change this. As a full-round action, a raktavarna's master can observe the world as if looking through the raktavarna's eyes. The master must concentrate to maintain this link each round. The master's visual senses are suppressed for this time, and he uses the raktavarna's darkvision, detect magic, and regular eyesight to observe the world. This ability has no limit on range, and functions even across planar boundaries. If the raktavarna is slain while its master is using this ability, the master is stunned for 1d4 rounds (no save)."},{"type":"Poison","kind":"Su","details":"Bite-injury; save Fort DC 13; frequency 1/round for 6 rounds; effect 1d2 Wis plus modify memory; cure 1 save. Each time a victim takes Wisdom damage from this poison, a modify memory effect causes the victim to forget the previous minute's interactions with the raktavarna, as long as the raktavarna is no longer visible or is in object form. The save DC is Constitution-based."}],"description":"Made up of smoke, blood, and gold, raktavarnas are the least of the rakshasas-they are born not from humanoids, but from the souls of rakshasas who failed utterly in their previous incarnation and who are thus reborn from a serpent's egg.\n\nThese terrors drift through society, passing from hand to hand as weapons or strange tokens from foreign lands, curiosities brought home by traders and emissaries and given to leaders as tribute. In this manner the raktavarnas gain entry into corridors of power throughout the world, and what they see, their foul masters know. A raktavarna's servitude to a master ends only when its master decrees, or (more commonly) upon the master's death. Little disconcerts raktavarnas more than having no master, and when they are cast adrift in this manner, they seek a replacement as soon as they can.\n\nA 7th-level lawful evil spellcaster with the Improved Familiar feat can gain a raktavarna rakshasa as a familiar.","ecology":"","habitat_society":""},{"name":"Rat Swarm","cr":2,"xp":600,"alignment":"N","size":"Tiny","type":"animal","subtypes":["swarm"],"init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":16,"hd":"3d8+3","hdvalue":3,"fort":4,"ref":5,"will":2,"defensive_abilities":["swarm traits"],"speed":[{"type":"land","speed":15},{"type":"climb","speed":15},{"type":"swim","speed":15}],"melee":"swarm (1d6 plus disease)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"disease"},{"type":"distraction","details":"DC 12"}],"strength":2,"dexterity":15,"constitution":13,"intelligence":2,"wisdom":13,"charisma":2,"baseatk":2,"feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Balance","value":6},{"skill":"Climb","value":10,"special":"use Dex instead of Str"},{"skill":"Perception","value":8},{"skill":"Stealth","value":14},{"skill":"Swim","value":10,"special":"use Dex instead of Str"}],"environments":["any"],"organizations":["solitary","pack (2-5 swarms)","infestation (6-12 swarms)"],"treasure":"none","description_visual":"A squirming, roiling mass of squeaking rats draws closer, teeth flashing and claws scratching everything in its path.","group":"Rat","source":"PFRPG Bestiary","special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth fever: Swarm- injury; save Fort DC 12; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"A rat swarm typically consists of a biting, roiling mass of hundreds of disease-ridden rats driven to uncharacteristic heights of aggression by fantastic and overwhelming hunger. In such numbers, they become voracious hunters, capable of killing a full-grown human with hundreds of bites. Rat swarms are often found in the sewers of large human settlements.\n\nRat swarms surround and attack any warm-blooded prey in their path.","ecology":"","habitat_society":""},{"name":"Ratling","cr":2,"xp":600,"alignment":"CE","size":"Tiny","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"},{"type":"low-light vision"}],"ac":16,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 dodge, +1 natural, +2 size","hp":19,"hd":"3d10+3","hdvalue":3,"fort":4,"ref":5,"will":1,"defensive_abilities":["evasion"],"immunities":["disease","poison"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10},{"type":"climb","speed":20},{"type":"swim","speed":30}],"melee":"bite +3 (1d3-2 plus bleed 1)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"read magic"},{"spell":"speak with animals","details":"rodents only"},{"spell":"spider climb"},{"spell":"tongues"}]},{"frequency":"1/day","spells":[{"spell":"summon swarm","details":"rat swarm only"}]},{"frequency":"3/day","spells":[{"spell":"cause fear"},{"spell":"dimension door"},{"spell":"invisibility","details":"self only"}]},{"frequency":"1/week","spells":[{"spell":"commune","details":"only when serving as a familiar"}]}],"strength":6,"dexterity":15,"constitution":13,"intelligence":12,"wisdom":10,"charisma":13,"baseatk":3,"cmb":3,"cmd":12,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Mobility"}],"skills":[{"skill":"Climb","value":6},{"skill":"Knowledge (planes)","value":4},{"skill":"Perception","value":6},{"skill":"Stealth","value":16},{"skill":"Swim","value":6}],"languages":["Aklo","speak with animals (rodents only)","tongues"],"sq":[{"type":"scroll use"}],"environments":["any urban"],"organizations":["solitary","conclave (2-20 plus 2-12 dire rats and 1-4 rat swarms)"],"treasure":"standard","description_visual":"This ratlike creature has tiny human hands in place of its front paws, and an unnerving human face with a toothy mouth.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Scroll Use","kind":"Ex","details":"A ratling can cast spells from any magic scroll as if it had the spell on its spell list."}],"description":"The ratling is a hideous amalgamation of rat and human: a long-haired rodent with handlike front paws and a face reminiscent of the face of a leering old man. Within the ratling's humanoid mouth are long, yellow incisors more akin to those one might find in the jaws of a rat. Ratlings are carnivores. While they can subsist on grubs, other rodents, and carrion, they prefer living food and fresh blood, particularly that of humanoid children and elderly folk. They also have a sense for magic, and lurk around temples and universities searching for scraps of knowledge or overlooked books and scrolls to steal. Ratlings associate with common rats and even mate with them, producing anything from large, aggressive rats (often with vestigial humanlike features or other sickening deformities) to infant ratlings to deformed rats. In a mixed litter, the infant ratling usually kills and eats its siblings, then arranges the dismembered and disemboweled corpses in semi-occult patterns. Elder ratlings often gain the advanced simple template or levels in cleric, oracle, witch, or wizard (a rare few gain rogue levels, especially if they associate with a thieves' guild or wererats). These elders often become leaders of their own kind, creating cabals organized like the universities they frequently inhabit. If the ratling can gain a familiar, it usually chooses a rat-an association that often brings with it more than mere supernatural companionship. Ratlings can never select another ratling as a familiar. A chaotic evil spellcaster can gain a ratling as a familiar at 7th level by taking the Improved Familiar feat. A ratling familiar gains commune once per week as a spell-like ability, which it can use on its master's behalf. The master usually allows the familiar to drink her blood at least once per week. A ratling measures just over 2 ft. long (although half that length is its long, ratty tail) and weighs 10 pounds.","ecology":"","habitat_society":""},{"name":"Ravenous Urchin Swarm","cr":2,"xp":600,"alignment":"NE","size":"Tiny","type":"vermin","subtypes":["aquatic","swarm"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":15,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+1 Dex, +2 natural, +2 size","hp":18,"hd":"4d8","hdvalue":4,"fort":4,"ref":2,"will":2,"immunities":["mind-affecting effects"],"resists":[{"type":"cold","value":5}],"speed":[{"type":"land","speed":10},{"type":"swim","speed":20}],"melee":"swarm +6 (2d6 plus poison)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 14"},{"type":"jet"},{"type":"underfoot"}],"strength":1,"dexterity":13,"constitution":10,"wisdom":13,"charisma":9,"baseatk":3,"cmb":2,"cmd":7,"cmd_special":"can't be tripped","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Swim","value":3}],"sq":[{"type":"amphibious"}],"environments":["any coastlines","any water"],"organizations":["solitary","pool (2-5)","red tide (11-20)"],"treasure":"none","description_visual":"A wave of swift-moving spines rushes forward-a roiling tide of dangerously fast sea urchins.","group":"Sea Urchin","source":"AP 56","special_abilities":[{"type":"Jet","kind":"Ex","details":"While underwater, a ravenous urchin swarm can jet as a full-round action at a speed of 70 ft. It must move in a straight line, but doesn't provoke attacks of opportunity while jetting."},{"type":"Poison","kind":"Ex","details":"Swarm-injury; save Fort DC 12; frequency 1/round for 6 rounds; effect 1d2 Dex and reduce movement speed by 10 ft. (to a minimum of 5 ft.); cure 1 save. The venom of ravenous urchin swarms stiffens muscles and locks joints into painful configurations. The save DC is Constitution-based."},{"type":"Underfoot","kind":"Ex","details":"Each time a creature moves through a space occupied by a ravenous urchin swarm or starts its movement in such a space, it runs the risk of a ravenous urchin moving underfoot. The creature must succeed at a DC 13 Reflex save or take 1 point of damage plus poison. Additionally, the affected creature's movement speed is reduced by half because its foot is wounded. This movement penalty lasts for 24 hours, until the creature is successfully treated with a DC 15 Heal check, or until it receives at least 1 point of magical healing. A charging or running creature must immediately stop if it steps on a ravenous urchin. Any creature moving at half its speed or slower can pick its way through a tidal pool of ravenous urchins (but not a ravenous urchin swarm) with no trouble. The save DC is Constitution-based."}],"description":"Unlike most urchins, the creatures that make up the infamous urchin swarms are capable of propelling themselves beneath the waves at furious speeds, creating a dangerous threat to pearl divers and other aquatic creatures-often one that's dismissed as a myth until it's far too late.","ecology":"","habitat_society":""},{"name":"River Elk","cr":2,"xp":600,"alignment":"N","size":"Large","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":11,"ac_flat_footed":11,"ac_mods":"+2 Dex, +2 natural, -1 size","hp":25,"hd":"3d8+12","hdvalue":3,"fort":7,"ref":7,"will":3,"speed":[{"type":"land","speed":50},{"type":"swim","speed":30}],"melee":"gore +4 (1d8+3) or 2 hooves -1 (1d6+1)","space":"10 ft.","reach":"5 ft.","strength":17,"dexterity":15,"constitution":18,"intelligence":2,"wisdom":15,"charisma":6,"baseatk":2,"cmb":6,"cmd":18,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Lightning Reflexes"},{"feat":"Run","type":"bonus"}],"skills":[{"skill":"Perception","value":8},{"skill":"Swim","value":11}],"environments":["cold plains","temperate plains"],"organizations":["solitary","pair","herd (3-50)"],"treasure":"none","description_visual":"This majestic beast stands the height of a man at its shoulders, a many-tipped rack of proud antlers crowning its head.","group":"Elk","source":"AP 31","description":"Powerful and swift land mammals, elk range through the plains, hills, and forests of many wildernesses, in great herds. Related to deer, elk prove important parts of many ecologies, being able to fend off or flee many threats while feeding greater predators. Their size, strength, and antlers-reaching up to 10 ft. wide on some males- allow them to contend with most of their environment's dangers, though herds generally favor flight to combat. Elk also prove exceptionably adaptable and remarkable survivors, capable of living through severe changes in weather and in a variety of environments without concern. Many humanoid cultures rely on elk herds, using them as valued food sources, work animals, and companions. Most breeds of elk stand between 3 and 5 ft. tall and weigh between 350 and 550 pounds, with females being far slighter than males. Heartier stock, such as the river elk seen throughout the River Kingdoms, Brevoy, and much of northern Avistan and Iobaria, grow to approximately 6 ft. tall and weigh between 700 and 1,100 pounds. In some secluded wilds, primeval megaloceros-massive ancestors of the elk-still flourish, standing up to 9 ft. tall, with bulks of 1,500 pounds and antlers growing over 12 ft. wide. In all species, only male elk grow antlers. Female elk have the same statistics as males, but lack the gore or powerful charge attacks. Ecology Elk live relatively long lives for herd animals, with some bulls living for over 15 years. Physiologically, they're similar to deer and other grazing animals with their patterns of travel and interaction with other creatures. Because of their size, though, they can damage an ecosystem, eating great amounts of food and sometimes competing with other herbivores for resources. Bull elk keep their antlers for about 7 to 8 months of the year, maintaining them as a primary form of defense. The antlers of common elk stand 4 ft. tall and spread about 6 ft. wide. Both bulls and cows are quite strong, their kicks proving deadly deterrents against many would-be attackers. Most breeds of elk stay in herds with upwards of 50 members. Herd members actively protect each other, doing what they can to defend those incapable of fleeing, yet also recognizing hopeless causes. Very few predators can stand up to a group of defensive elk, though wolves, bears, boars, and hunting cats often attack the young, sick, or unwary who venture away from the herd. While most natural predators steer clear of elk herds, many humanoid or monstrous hunters manage to pick off elk by relying on ranged weapons or great physical prowess. Habitat & Society During most of the year, elk maintain large groups of their own genders. Cows and the young tend to stick near dens, so bulls are more likely to be found wandering their wide territories. During mating season, a dominant bull maintains a harem of as many as 20 cows. Any threat to that establishment is met with violent force, with battles between rivals often resulting in fierce clashing of antlers and contests of strength-though such rarely prove deadly. During mating season, cows don't always produce offspring, though when they do, typically only one or two elk are born. After mating season, cows care for calves for only a short time. Most are only nursed for a couple of months before they join with the rest of the herd. Elk are hibernating creatures, being almost unheard of during the winter season. During the remainder of the year, they roam and graze widely. When they make their tell-tale noise (called bugling,) it booms and echoes for miles, and females often consider the loudest males the most suitable as mates. Elk migrate throughout the year, typically to avoid the snow. They move from low to high ground, where tree bark is an abundant food source. During the summer months, they graze on the grasses they can find. During dry seasons, elk often make great trips to find abundant food sources, which can sometimes force out lesser creatures from a habitat. Elk are also know to vary widely from region to region. Common in Brevoy, the River Kingdoms, and secluded spots of Numeria, river elks prove larger and heartier than most of their brethren. Named for their tendencies to travel along rivers and the comfort with which they enter water, these elk exhibit a daring unknown to most other breeds, the bulls willingly fighting to defend their herds from any perceived threats. Megaloceros Similar in form to the elk but far superior in size is the megaloceros. The average male is a towering, dangerous creature with antlers that can alone weigh nearly 100 pounds. Unlike elk, megaloceros antlers are decidedly enormous and sometimes wider than their bodies are long. This leads to common misconceptions and exaggerations about the creature's monstrous size. Conveniently for those pursued, megaloceros males have difficultly navigating thickly forested areas, making them natives of plains and the woods' edge.","ecology":"Elk live relatively long lives for herd animals, with some bulls living for over 15 years. Physiologically, they're similar to deer and other grazing animals with their patterns of travel and interaction with other creatures. Because of their size, though, they can damage an ecosystem, eating great amounts of food and sometimes competing with other herbivores for resources. Bull elk keep their antlers for about 7 to 8 months of the year, maintaining them as a primary form of defense. The antlers of common elk stand 4 ft. tall and spread about 6 ft. wide. Both bulls and cows are quite strong, their kicks proving deadly deterrents against many would-be attackers. Most breeds of elk stay in herds with upwards of 50 members. Herd members actively protect each other, doing what they can to defend those incapable of fleeing, yet also recognizing hopeless causes. Very few predators can stand up to a group of defensive elk, though wolves, bears, boars, and hunting cats often attack the young, sick, or unwary who venture away from the herd. While most natural predators steer clear of elk herds, many humanoid or monstrous hunters manage to pick off elk by relying on ranged weapons or great physical prowess.","habitat_society":"During most of the year, elk maintain large groups of their own genders. Cows and the young tend to stick near dens, so bulls are more likely to be found wandering their wide territories. During mating season, a dominant bull maintains a harem of as many as 20 cows. Any threat to that establishment is met with violent force, with battles between rivals often resulting in fierce clashing of antlers and contests of strength-though such rarely prove deadly. During mating season, cows don't always produce offspring, though when they do, typically only one or two elk are born. After mating season, cows care for calves for only a short time. Most are only nursed for a couple of months before they join with the rest of the herd. Elk are hibernating creatures, being almost unheard of during the winter season. During the remainder of the year, they roam and graze widely. When they make their tell-tale noise (called bugling,) it booms and echoes for miles, and females often consider the loudest males the most suitable as mates. Elk migrate throughout the year, typically to avoid the snow. They move from low to high ground, where tree bark is an abundant food source. During the summer months, they graze on the grasses they can find. During dry seasons, elk often make great trips to find abundant food sources, which can sometimes force out lesser creatures from a habitat. Elk are also know to vary widely from region to region. Common in Brevoy, the River Kingdoms, and secluded spots of Numeria, river elks prove larger and heartier than most of their brethren. Named for their tendencies to travel along rivers and the comfort with which they enter water, these elk exhibit a daring unknown to most other breeds, the bulls willingly fighting to defend their herds from any perceived threats. Megaloceros Similar in form to the elk but far superior in size is the megaloceros. The average male is a towering, dangerous creature with antlers that can alone weigh nearly 100 pounds. Unlike elk, megaloceros antlers are decidedly enormous and sometimes wider than their bodies are long. This leads to common misconceptions and exaggerations about the creature's monstrous size. Conveniently for those pursued, megaloceros males have difficultly navigating thickly forested areas, making them natives of plains and the woods' edge."},{"name":"Rust-Risen","cr":2,"xp":600,"alignment":"CE","size":"Medium","type":"undead","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 natural","hp":19,"hd":"3d8+6","hdvalue":3,"fort":3,"ref":2,"will":4,"defensive_abilities":["absorb electricity"],"immunities":["undead traits"],"weaknesses":["malfunction"],"speed":[{"type":"land","speed":30}],"melee":"arm drill +5 (1d6+3), metal jaw +5 (1d6+3)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":13,"intelligence":5,"wisdom":12,"charisma":14,"baseatk":2,"cmb":5,"cmd":16,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Intimidate","value":6},{"skill":"Perception","value":7},{"skill":"Stealth","value":5}],"languages":["Common"],"sq":[{"type":"augmentations"}],"environments":["any"],"organizations":["solitary","pair","pack (3-12)"],"treasure":"none","description_visual":"Miscellaneous bits of rusted machinery are fused to the body of this shambling corpse.","source":"AP 86","special_abilities":[{"type":"Absorb Electricity","kind":"Ex","details":"When a rust-risen is damaged by electricity, it takes no damage (as if immune). Instead, the rust-risen gains 1 temporary hit point for every 4 points of damage it would have taken. A rust-risen can only have a number of temporary hit points equal to 150% of its hit point total. These temporary hit points disappear 1 hour later. If a rust-risen takes more than double its normal hit point total in electricity damage from a single attack, the creature is destroyed."},{"type":"Augmentations","kind":"Ex","details":"Rust-risen have various pieces of malfunctioning machinery embedded in their bodies. Each of these augmentations provides the rust-risen with different abilities. A rust-risen has one augmentation plus one additional augmentation for every 3 Hit Dice the creature possesses (typically 2 for most rust-risen). The rust-risen presented here has the arm drill and metal jaw augmentations."},{"type":"Malfunction","kind":"Ex","details":"The machinery embedded in a rust-risen functions unpredictably in stressful situations. When a rust-risen enters combat, there is a cumulative 1% chance each round that it malfunctions. This chance resets to 0% 1 minute after combat ends. When a rust-risen malfunctions, it takes a -2 penalty on attack rolls, saving throws, skill checks, and ability checks for 1d4 minutes."}],"description":"Rust-risen lurk n the burned-out husks of ancient space-faring vessels and among the grease and blood stained laboratories of mad, technologist necromancers. These hideous undead mockeries riddled with the remnants of ancient technology-rotting creatures, outfitted with twitching relics of a space-faring race, that prey on the living by tearing their victims to shreds with gnashing drills, vivisecting scalpels, and flailing exsanguination tubes.\n\nEcology\n\nNecromancers with a twisted affinity for technology often forgo the usual ghoul or\n\nzombie minions for a rust-risen ally. Far from mindless, rust-risen possess limited memories of their lives before undeath, though these recollections are more like misshapen shadows flickering on the walls of their minds, and are often distorted and highly inaccurate.\n\nHabitat & Society\n\nRust-risen possess the unnatural hunger for the living shared by other undead, but they also maintain a strange obsession with technological artifacts. It's not uncommon when breaching a rust-risen lair to find it filled with baubles, gizmos, and other technological oddities-even schematics which rust-risen cannot make sense of. Rust-risen collect such items, which appear to give them some semblance of comfort in their rotting horror of an existence. Rust-risen also seek sources of electrical power, finding them comforting in the same way a warm bath soothes living flesh. If denied access to an electrical power source, rust-risen become sluggish and despondent, but spring to activity as soon as they are exposed to electricity.\n\nRust-risen are always bonded to their creator, serving them as loyally as an animal companion does its master. They rely on their creator to keep their malfunctioning technology from completely breaking down. Over time however, their bond grows into obsession; eventually it becomes an uncontrollable desire for their master to join them in undeath. Such obsessed rust-risen often overpower their necromancer overlords, who awaken to find themselves on an operating table, their machine-studded monstrosities hovering busily over their extracted viscera.\n\nIf a rust-risen's creator is destroyed, the undead becomes despondent and lost. It wanders, avoiding civilization and hovering at the fringes of communities, preying on stragglers and wallowing in misanthropic misery. At the same time, it constantly seeks the aid of anyone who can keep it from breaking down. This duality means that the mood of an uncontrolled rust-risen is nigh-impossible to predict.\n\nRust-Risen Augmentations As rust-risen are cobbled together from dead bodies augmented with barely-functioning machinery, no two are exactly alike. Some technologically minded necromancers with enough raw materials and a consistent design plan try to make their rust-risen conform to a template, but most packs of rust-risen are motley and violent amalgamations of flesh and steel.\n\nA GM can further modify rust-risen in their games with augmentations of their own creation, but they should be no more powerful than those described below.\n\nAdditional Appendage: Some rust-risen are augmented with an additional mechanical limb. A rust-risen with this augmentation gains a slam attack that deals damage appropriate for its size (1d4 for most rust-risen). This arm\n\ncan manipulate objects as well as a normal arm, but cannot be used to wield a weapon.\n\nAntifreeze: A rust-risen with this augmentation has an embedded series of tubes connected to a pump that keeps a chemical flowing through its body, preventing ice from forming inside it. The rust-risen gains resistance 5 to cold.\n\nArm Drill: A rust-risen with this augmentation has a deadly, spinning drill grafted onto its forearm. The rust-risen can use the drill to make a melee attack that deals 1d6 points of bludgeoning, piercing, and slashing damage.\n\nCling Hooks: A rust-risen with this augmentation has barbed hooks grafted into its arms and legs. The rust-risen gains a +4 racial bonus on Climb checks and a +4 racial bonus on combat maneuvers to grapple opponents.\n\nCutting Arm: A rust-risen with this augmentation has one of its forearms replaced with a functional laser torch. The rust-risen deals 1d10 points of fire damage as a touch attack. This damage isn't modified further by Strength. When the laser torch is used as a tool or as a weapon to sunder, damage dealt by it bypasses hardness up to 20 points and isn't halved (as is normally the case for energy damage applied to objects) unless the object is fire resistant. A laser torch's cutting beam passes through a force field and force effect without damaging that field. Invisible objects and creatures cannot be harmed by a laser torch.\n\nEviscerator: A rust-risen with the eviscerator augmentation has a number of twisting blades, reciprocating saws, and spinning drills built into its chest. The rust-risen deals an additional 1d8 points of damage when grappling.\n\nExsanguination Tubes: A rust-risen with exsanguination tubes can drain blood from creatures it has grappled. If the rust-risen establishes or maintains a pin, it bleeds the target, dealing 1 point of Constitution damage.\n\nMetal Jaw: A rust-risen with this augmentation has a metal jaw replacing its natural one. The rust-risen gains a bite attack that deals damage appropriate for its size (1d6 points of damage for most rust-risen).\n\nMulti-tool: A rust-risen with this augmentation has at least one of its hands replaced with a variety of tools. The rust-risen gains a +4 competence bonus on Disable Device checks and is considered to be trained in that skill. The rust-risen also gains a +2 competence bonus on one specific Craft skill.\n\nSteel Clad: A rust-risen with this augmentation has sheets of metal riveted to is body. The rust-risen gains a +2 natural armor bonus.\n\nTripod: A rust-risen with this augmentation has an additional mechanical leg. The rust-risen gains a +2 bonus to CMD against overrun and trip attempts and a +2 bonus on Acrobatics when moving on narrow surfaces or uneven ground. The rust-risen isn't considered flat-footed nor does it lose its Dexterity bonus to AC when using Acrobatics in this way.","ecology":"Necromancers with a twisted affinity for technology often forgo the usual ghoul or\n\nzombie minions for a rust-risen ally. Far from mindless, rust-risen possess limited memories of their lives before undeath, though these recollections are more like misshapen shadows flickering on the walls of their minds, and are often distorted and highly inaccurate.","habitat_society":"Rust-risen possess the unnatural hunger for the living shared by other undead, but they also maintain a strange obsession with technological artifacts. It's not uncommon when breaching a rust-risen lair to find it filled with baubles, gizmos, and other technological oddities-even schematics which rust-risen cannot make sense of. Rust-risen collect such items, which appear to give them some semblance of comfort in their rotting horror of an existence. Rust-risen also seek sources of electrical power, finding them comforting in the same way a warm bath soothes living flesh. If denied access to an electrical power source, rust-risen become sluggish and despondent, but spring to activity as soon as they are exposed to electricity.\n\nRust-risen are always bonded to their creator, serving them as loyally as an animal companion does its master. They rely on their creator to keep their malfunctioning technology from completely breaking down. Over time however, their bond grows into obsession; eventually it becomes an uncontrollable desire for their master to join them in undeath. Such obsessed rust-risen often overpower their necromancer overlords, who awaken to find themselves on an operating table, their machine-studded monstrosities hovering busily over their extracted viscera.\n\nIf a rust-risen's creator is destroyed, the undead becomes despondent and lost. It wanders, avoiding civilization and hovering at the fringes of communities, preying on stragglers and wallowing in misanthropic misery. At the same time, it constantly seeks the aid of anyone who can keep it from breaking down. This duality means that the mood of an uncontrolled rust-risen is nigh-impossible to predict.\n\nRust-Risen Augmentations As rust-risen are cobbled together from dead bodies augmented with barely-functioning machinery, no two are exactly alike. Some technologically minded necromancers with enough raw materials and a consistent design plan try to make their rust-risen conform to a template, but most packs of rust-risen are motley and violent amalgamations of flesh and steel.\n\nA GM can further modify rust-risen in their games with augmentations of their own creation, but they should be no more powerful than those described below.\n\nAdditional Appendage: Some rust-risen are augmented with an additional mechanical limb. A rust-risen with this augmentation gains a slam attack that deals damage appropriate for its size (1d4 for most rust-risen). This arm\n\ncan manipulate objects as well as a normal arm, but cannot be used to wield a weapon.\n\nAntifreeze: A rust-risen with this augmentation has an embedded series of tubes connected to a pump that keeps a chemical flowing through its body, preventing ice from forming inside it. The rust-risen gains resistance 5 to cold.\n\nArm Drill: A rust-risen with this augmentation has a deadly, spinning drill grafted onto its forearm. The rust-risen can use the drill to make a melee attack that deals 1d6 points of bludgeoning, piercing, and slashing damage.\n\nCling Hooks: A rust-risen with this augmentation has barbed hooks grafted into its arms and legs. The rust-risen gains a +4 racial bonus on Climb checks and a +4 racial bonus on combat maneuvers to grapple opponents.\n\nCutting Arm: A rust-risen with this augmentation has one of its forearms replaced with a functional laser torch. The rust-risen deals 1d10 points of fire damage as a touch attack. This damage isn't modified further by Strength. When the laser torch is used as a tool or as a weapon to sunder, damage dealt by it bypasses hardness up to 20 points and isn't halved (as is normally the case for energy damage applied to objects) unless the object is fire resistant. A laser torch's cutting beam passes through a force field and force effect without damaging that field. Invisible objects and creatures cannot be harmed by a laser torch.\n\nEviscerator: A rust-risen with the eviscerator augmentation has a number of twisting blades, reciprocating saws, and spinning drills built into its chest. The rust-risen deals an additional 1d8 points of damage when grappling.\n\nExsanguination Tubes: A rust-risen with exsanguination tubes can drain blood from creatures it has grappled. If the rust-risen establishes or maintains a pin, it bleeds the target, dealing 1 point of Constitution damage.\n\nMetal Jaw: A rust-risen with this augmentation has a metal jaw replacing its natural one. The rust-risen gains a bite attack that deals damage appropriate for its size (1d6 points of damage for most rust-risen).\n\nMulti-tool: A rust-risen with this augmentation has at least one of its hands replaced with a variety of tools. The rust-risen gains a +4 competence bonus on Disable Device checks and is considered to be trained in that skill. The rust-risen also gains a +2 competence bonus on one specific Craft skill.\n\nSteel Clad: A rust-risen with this augmentation has sheets of metal riveted to is body. The rust-risen gains a +2 natural armor bonus.\n\nTripod: A rust-risen with this augmentation has an additional mechanical leg. The rust-risen gains a +2 bonus to CMD against overrun and trip attempts and a +2 bonus on Acrobatics when moving on narrow surfaces or uneven ground. The rust-risen isn't considered flat-footed nor does it lose its Dexterity bonus to AC when using Acrobatics in this way."},{"name":"Sahuagin","cr":2,"xp":600,"alignment":"LE","size":"Medium","type":"monstrous humanoid","subtypes":["aquatic"],"init":1,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+1 Dex, +5 natural","hp":15,"hd":"2d10+4","hdvalue":2,"fort":4,"ref":4,"will":4,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"trident +4 (1d8+3), bite -1 (1d4+1) or 2 claws +4 (1d4+2),  bite +4 (1d4+2)","ranged":"heavy crossbow +3 (1d10/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood frenzy"}],"strength":14,"dexterity":13,"constitution":14,"intelligence":14,"wisdom":13,"charisma":9,"baseatk":2,"cmb":4,"cmd":15,"feats":[{"feat":"Great Fortitude"}],"skills":[{"skill":"Handle Animal","value":1},{"skill":"Perception","value":6},{"skill":"Ride","value":6},{"skill":"Stealth","value":6},{"skill":"Survival","value":6},{"skill":"Swim","value":15}],"languages":["Aquan","Common","speak with sharks"],"environments":["temperate oceans","warm oceans"],"organizations":["Solitary","pair","team (5-8)","patrol (11-20 plus 1 lieutenant of 3rd level and 1-2 sharks)","band (20-80 plus 100% noncombatants, 1 lieutenant of 3rd level and 1 chieftain of 4th level per 20 adults, and 1-2 sharks)","tribe (70-160 plus 100% noncombatants, 1 lieutenant of 3rd level per 20 adults, 1 chieftain of 4th level per 40 adults, 9 guards of 4th level, 1-4 underpriestesses of 3rd-6th level, 1 priestess of 7th level, 1 baron of 6th-8th level, and 5-8 sharks)"],"treasure":"none","description_visual":"This scaly humanoid has a long, fish-like tail. Its arms and legs end in webbed claws, and its piscine head features a toothy maw.","source":"PFRPG Bestiary","special_abilities":[{"type":"Blood Frenzy","kind":"Ex","details":"Once per day, a sahuagin that takes damage in combat can fly into a frenzy in the following round. It gains +2 Constitution and +2 Strength, but takes a -2 penalty to its AC. The frenzy lasts as long as the battle or 1 minute, whichever is shorter."},{"type":"Speak with Sharks","kind":"Su","details":"A sahuagin can communicate telepathically with sharks to a distance of 150 ft. This communication is limited to simple concepts, such as \"come here,\" \"defend me,\" or \"attack this target.\""}],"description":"Ravenous and cruel, the sahuagin are, unfortunately, among the most prosperous oceanic races. Great cities raised by these creatures darken the deep ocean trenches, and many are the near-coastal fortresses where they launch endless raids against their air-breathing enemies who dwell in close proximity to the shore. Warlike and proud, the sahuagin rarely ally with others, and view most other aquatic races such as the aboleths, the merfolk, and their ilk as competitors. The only creatures they seem to respect and adore apart from their own kind are sharks, for in these relentless predators the sahuagin see much of themselves. A sahuagin stands 7 ft. tall and weighs about 250 pounds.\n\nSahuagin are prone to beneficial mutations, and when a mutant is born it almost always rises to the society's nobility or rulership. The most common sahuagin mutation is an extra pair of arms (granting two additional claw attacks or the opportunity to wield more weapons).\n\nRumors speak of the rare malenti-sahuagin who look not like sharkmen but aquatic elves, yet who share their kin's bloodlusts and cruel natures. Malenti often serve as spies and assassins for sahuagin rulers, but rumors of allmalenti tribes in isolated reaches of the sea persist.","ecology":"","habitat_society":"","gear":"trident, heavy crossbow  with 10 bolts"},{"name":"Sasquatch","cr":2,"xp":600,"alignment":"N","size":"Medium","type":"humanoid","subtypes":["sasquatch"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":22,"hd":"3d8+9","hdvalue":3,"fort":4,"ref":5,"will":1,"speed":[{"type":"land","speed":40}],"melee":"club +8 (1d6+9) or   slam +8 (1d4+9)","ranged":"rock +5 (1d4+9)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rock throwing","details":"120 ft."}],"strength":22,"dexterity":15,"constitution":16,"intelligence":9,"wisdom":10,"charisma":11,"baseatk":2,"cmb":8,"cmd":20,"feats":[{"feat":"Self-Sufficient"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Heal","value":2},{"skill":"Perception","value":5},{"skill":"Stealth","value":10,"special":"+14 in forested areas"},{"skill":"Survival","value":10}],"languages":["Sasquatch"],"sq":[{"type":"pungency"},{"type":"woodland stride"}],"environments":["cold forests","temperate forests"],"organizations":["solitary","pair","family (3-7)"],"treasure":"standard","description_visual":"Tall, burly, and hairy, this humanoid creature wields a large tree branch for a club and has a swinging, apelike gait.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Pungency","kind":"Ex","details":"A sasquatch's odor is quite powerful, and can be detected at twice the normal distance by scent."},{"type":"Woodland Stride","kind":"Ex","details":"A sasquatch can move through any sort of undergrowth (such as natural thorns, briars, overgrown areas, and similar terrain) at normal speed and without taking damage or suffering any other impairment. Undergrowth that has been magically manipulated to impede movement still affects the sasquatch."}],"description":"The elusive sasquatches earn their mysterious reputation rightly; they live in unpopulated forests and avoid confrontations with humanoids, only becoming violent when they feel threatened, when their territory is encroached upon, or when they feel they must protect their young. Left to their own devices, sasquatch families are perfectly content to live their lives in the deep woods, leaving behind little to no trace of their passing save for the periodic big footprint in the ground.\n\nDespite their considerable bulk, sasquatches are incredibly stealthy creatures, capable of moving through forests in particular with astonishing grace and efficiency. The one trait that somewhat undermines sasquatches' stealth is their distinctive odor-a pungent, musky scent that is often noticeable even when the hidden sasquatches themselves are not apparent.\n\nThe elusiveness of sasquatches is such that even in a world where dragons and sea monsters are real, many urban scholars doubt the existence of the creatures, citing the lack of evidence of sasquatch lairs or remains as proof of their nonexistence. In truth, sasquatches are simply far more efficient at living in harmony with nature than most humanoids could ever hope to be. To a sasquatch, a deadfall in a forest makes a perfectly fine home. When a sasquatch dies, its kin take pains to bury the body deep and hide all trace of the gravesite to protect the remains from scavengers and evil spirits alike. The sasquatch tongue is a relatively complex language that mixes vocalizations, howls, and \"knocking\"-the act of striking a solid surface (like a tree or boulder) with a club or stone-and thus tends to blend in with the ambient sounds of a forest.\n\nA sasquatch is 8 ft. tall and weighs 570 pounds. Rural populaces often have fond nicknames for these creatures, such as wild men, skunk apes, and perhaps most popularly, simply bigfoot.","ecology":"","habitat_society":""}];
